use sqlparser::ast::{BinaryOperator, Expr, Ident, SelectItem, SetExpr, Statement};
use sqlparser::dialect::*;
use sqlparser::parser::Parser;

fn parse(d: &dyn Dialect, sql: &str) -> Vec<Statement> {
    Parser::parse_sql(d, sql)
        .unwrap_or_else(|e| panic!("{d:?}: {sql}\n{e}"))
}

fn projections(ast: &[Statement]) -> Vec<Expr> {
    assert_eq!(ast.len(), 1, "expected one statement: {ast:?}");
    match &ast[0] {
        Statement::Query(query) => match query.body.as_ref() {
            SetExpr::Select(select) => select.projection.iter().map(|item| {
                match item {
                    SelectItem::UnnamedExpr(expr) => expr.clone(),
                    other => panic!("expected unnamed expression: {other:?}"),
                }
            }).collect(),
            other => panic!("expected SELECT: {other:?}"),
        },
        other => panic!("expected query: {other:?}"),
    }
}

fn expression(d: &dyn Dialect, text: &str) -> Expr {
    let items = projections(&parse(d, &format!("SELECT {text}")));
    assert_eq!(items.len(), 1, "not a single expression: {text}");
    items[0].clone()
}

fn operand(d: &dyn Dialect, text: &str) -> Expr {
    if text.starts_with("SELECT ") || text.starts_with("WITH ") {
        let ast = parse(d, text);
        assert_eq!(ast.len(), 1);
        match &ast[0] {
            Statement::Query(query) => Expr::Subquery(query.clone()),
            other => panic!("expected subquery: {other:?}"),
        }
    } else {
        expression(d, text)
    }
}

fn quantified(d: &dyn Dialect, q: &str, op: BinaryOperator, right: Expr) -> Expr {
    let left = Box::new(expression(d, "a"));
    let right = Box::new(right);
    match q {
        "ANY" | "SOME" => Expr::AnyOp {
            left, compare_op: op, right, is_some: q == "SOME",
        },
        "ALL" => Expr::AllOp { left, compare_op: op, right },
        _ => panic!("unknown quantifier: {q}"),
    }
}

fn rhs<'a>(expr: &'a Expr, q: &str) -> &'a Expr {
    match expr {
        Expr::AnyOp { left, compare_op, right, is_some } => {
            assert!(q == "ANY" || q == "SOME");
            assert_eq!(*is_some, q == "SOME", "quantifier changed: {expr:?}");
            assert_eq!(left.as_ref(), &Expr::Identifier(Ident::new("a")));
            assert_eq!(compare_op, &BinaryOperator::Eq);
            right.as_ref()
        },
        Expr::AllOp { left, compare_op, right } => {
            assert_eq!(q, "ALL");
            assert_eq!(left.as_ref(), &Expr::Identifier(Ident::new("a")));
            assert_eq!(compare_op, &BinaryOperator::Eq);
            right.as_ref()
        },
        other => panic!("expected {q} comparison: {other:?}"),
    }
}

fn roundtrip(d: &dyn Dialect, sql: &str, ast: &[Statement]) {
    let plain = ast.iter().map(ToString::to_string).collect::<Vec<_>>().join("; ");
    let pretty = ast.iter().map(|s| format!("{s:#}")).collect::<Vec<_>>().join(";\n");
    for rendered in [plain, pretty] {
        let reparsed = parse(d, &rendered);
        assert_eq!(ast, reparsed.as_slice(),
            "{d:?}: AST changed after formatting {sql}\nOutput:\n{rendered}");
    }
    #[cfg(feature = "json_example")]
    {
        let encoded = serde_json::to_string(ast).unwrap();
        let decoded: Vec<Statement> = serde_json::from_str(&encoded).unwrap();
        assert_eq!(ast, decoded.as_slice(), "serde changed {sql}");
    }
}

fn check(d: &dyn Dialect, sql: &str, expected: &[Expr]) -> Vec<Statement> {
    let ast = parse(d, sql);
    assert_eq!(projections(&ast).as_slice(), expected,
        "{d:?}: wrong expression structure for {sql}");
    roundtrip(d, sql, &ast);
    ast
}

fn operands(d: &dyn Dialect, q: &str) {
    for text in [
        "b", "1", "NULL", "TRUE", "b OR c", "b AND c", "b = c",
        "NOT b", "NOT b = c AND d OR e", "b OR c AND d",
        "b = c OR d = e", "(b OR c) AND NOT (d = e)",
        "(b)", "((b OR c))", "(b, c)", "ARRAY[1, 2]",
    ] {
        // The ordinary expression entry supplies the chosen dialect's
        // existing precedence, independently of the outer comparison.
        let expected = quantified(d, q, BinaryOperator::Eq, expression(d, text));
        check(d, &format!("SELECT a = {q}({text})"), &[expected]);
    }
}

fn boundaries(d: &dyn Dialect, q: &str) {
    for text in [
        "b", "b OR c", "SELECT b FROM t",
        "WITH x AS (SELECT b FROM t) SELECT b FROM x",
        "SELECT b FROM t WHERE (b > 0 AND c) UNION SELECT d FROM u",
        "SELECT b FROM t WHERE b IN (SELECT c FROM u)",
