            assert_eq!(*is_some, q == "SOME", "quantifier changed: {expr:?}");
            assert_eq!(left.as_ref(), &Expr::Identifier(Ident::new("a")));
            assert_eq!(compare_op, &BinaryOperator::Eq);
            right.as_ref()
        },
        Expr::AllOp { left, compare_op, right } => {
            assert_eq!(q, "ALL");
            assert_eq!(left.as_ref(), &Expr::Identifier(Ident::new("a")));
            assert_eq!(compare_op, &BinaryOperator::Eq);
            right.as_ref()
        },
        other => panic!("expected {q} comparison: {other:?}"),
    }
}

fn roundtrip(d: &dyn Dialect, sql: &str, ast: &[Statement]) {
    let plain = ast.iter().map(ToString::to_string).collect::<Vec<_>>().join("; ");
    let pretty = ast.iter().map(|s| format!("{s:#}")).collect::<Vec<_>>().join(";\n");
    for rendered in [plain, pretty] {
        let reparsed = parse(d, &rendered);
        assert_eq!(ast, reparsed.as_slice(),
            "{d:?}: AST changed after formatting {sql}\nOutput:\n{rendered}");
    }
    #[cfg(feature = "json_example")]
    {
        let encoded = serde_json::to_string(ast).unwrap();
        let decoded: Vec<Statement> = serde_json::from_str(&encoded).unwrap();
        assert_eq!(ast, decoded.as_slice(), "serde changed {sql}");
    }
}

