#[cfg(feature = "visitor")]
fn between_symmetric_visitor() {
    use sqlparser::ast::{visit_expressions, visit_expressions_mut};

    // The comparison target and both bounds are visited, as with a
    // plain `BETWEEN`.
    let stmt = pg_and_generic().verified_stmt("SELECT x BETWEEN SYMMETRIC 1 AND 2 FROM t");
    let mut visited = vec![];
    let _ = visit_expressions(&stmt, |expr| {
        visited.push(expr.to_string());
        core::ops::ControlFlow::<()>::Continue(())
    });
    assert_eq!(
        visited,
        ["x BETWEEN SYMMETRIC 1 AND 2", "x", "1", "2"]
    );

    // ...and can be modified in place.
    let mut stmt =
        pg_and_generic().verified_stmt("SELECT x NOT BETWEEN ASYMMETRIC 1 AND 2 FROM t");
    let _ = visit_expressions_mut(&mut stmt, |expr| {
        if let Expr::ModifiedBetween { low, high, .. } = expr {
            *low = Box::new(Expr::value(Value::Number("10".to_string(), false)));
            *high = Box::new(Expr::value(Value::Number("20".to_string(), false)));
        }
        core::ops::ControlFlow::<()>::Continue(())
    });
    assert_eq!(
        "SELECT x NOT BETWEEN ASYMMETRIC 10 AND 20 FROM t",
        stmt.to_string()
    );
}

